def normalize_path(path: str) -> str:
    """
    Normalize a Unix-style POSIX path by resolving '.' and '..' components
    and collapsing redundant separators.
    """
    if not path:
        return "."

    is_absolute = path.startswith("/")

    # Split on '/' and filter out empty strings and '.' components
    parts = path.split("/")

    stack = []
    for part in parts:
        if part == "" or part == ".":
            # Skip empty parts (from multiple slashes or trailing slash) and '.'
            continue
        elif part == "..":
            if stack and stack[-1] != "..":
                # Pop the last component
                stack.pop()
            elif is_absolute:
                # At root, '..' stays at root (do nothing)
                pass
            else:
                # Relative path: preserve leading '..' components
                stack.append("..")
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    else:
        result = "/".join(stack)
        return result if result else "."
